      "key_provisions": "แบ่งเป็น 2 หมวด: หมวด 1 การปรับงบประมาณระหว่างปี กรณีกระทบ OKRs ตามโปรแกรม/แผนงาน/โครงการ ให้ยื่นคำขอปรับต่อ สกสว. ได้ 'ไตรมาสละ 1 ครั้ง' เสนอคณะอนุกรรมการแผนและกรอบงบฯ กลั่นกรองก่อนเสนอ กสว. อนุมัติและทำคำรับรองฯ ใหม่ (ข้อ 6–8); หมวด 2 การจัดทำคำขอและจัดสรรงบเพื่อการวิจัยที่สำคัญและจำเป็นเร่งด่วนนอกแผนประจำปี เพื่อดำเนินการตามข้อสั่งการนายกรัฐมนตรี มติ ครม. หรือมติสภานโยบาย โดยต้องระบุผู้ใช้ประโยชน์ชัดเจนและคำนึงถึงเงินกองทุนคงเหลือ/กระแสเงินสด (ข้อ 9–12) | วันประกาศ/มติ: มติ กสว. ครั้งที่ 1/2564 (15 ม.ค. 2564) | ประกาศ ณ วันที่ 21 ม.ค. 2564 (13 ข้อ) | เชื่อมคู่มือ/SOP: คู่มือ FF บทที่ 3 ข้อ 5 (การปรับแผนและงบประมาณระหว่างปีงบประมาณ) | กฎหมายระดับที่ 3: พ.ร.บ.วิธีการงบประมาณ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0102) และ พ.ร.บ.วินัยการเงินการคลังของรัฐ พ.ศ. 2561 (หมวด 12: TSRI-DOC-0103)",
