      "key_provisions": "กำหนดกลไกสนับสนุนทุนสำหรับภาคเอกชนตามความต้องการภาครัฐหรืออุปสงค์ตลาด (Thai Business Innovation Research: TBIR) โดย กสว. กำหนดประเด็นวิจัย PMU ที่รับผิดชอบ และกรอบวงเงินเป็นรายปี (ข้อ 4–5); แบ่งการดำเนินการเป็น 3 ระยะ (ข้อ 6 วรรคสอง): ระยะที่ 1 การศึกษาความเป็นไปได้ (Feasibility Study), ระยะที่ 2 การพัฒนาต้นแบบ (Prototype Development) [ใช้เงินอุดหนุนกองทุนตามสัดส่วนร้อยละที่ กสว. กำหนด] และระยะที่ 3 การมุ่งเน้นใช้ประโยชน์เชิงพาณิชย์ (Commercialization) [ใช้กลไกและมาตรการอื่นสนับสนุน] | วันประกาศ/มติ: มติ กสว. ครั้งที่ 2/2564 (19 ก.พ. 2564) | ประกาศ ณ วันที่ 19 ก.พ. 2564 (11 ข้อ) | เชื่อมคู่มือ/SOP: แนวทางการจัดสรรงบ Strategic Fund (SF) สำหรับภาคเอกชนของสำนัก F3 และ F4 | กฎหมายระดับที่ 3: พ.ร.บ.ส่งเสริมการใช้ประโยชน์ผลงานวิจัยและนวัตกรรม พ.ศ. 2564 (TRIUP Act) และ พ.ร.บ.การจัดซื้อจัดจ้างฯ พ.ศ. 2560 (หมวด 12: TSRI-DOC-0104) (เชื่อม พ.ร.บ.ส่งเสริมฯ ม.29(1))",
