      "text": "ให้กระทรวง กสว. และ สอวช. โดยความเห็นชอบของสภานโยบายส่งเสริม และสนับสนุนการผลิตและพัฒนาบุคลากรที่มีคุณภาพ มีความสามารถในการพัฒนาวิ",
