      "text": "ให้ส านักงานการวิจัยแห่งชาติรวบรวม วิเคราะห์ สังเคราะห์ข้อมูลการด าเนินการ และผลงานวิจัยและนวัตกรรมจากหน่วยงานในระบบวิจัยและนวัตกร",
