      "scenario_stem": "ภายหลังการบังคับใช้ พ.ร.บ.การส่งเสริม ววน. (ฉบับที่ 2) พ.ศ. 2568 ซึ่งแก้ไขเพิ่มเติมมาตรา 18 ประกอบประกาศ กสว. เรื่องหลักเกณฑ์การจัดทำคำของบประมาณ (ฉบับที่ 3) พ.ศ. 2569 ข้อ 44, 44/1 และ 44/2 กลไกการจัดสรรงบประมาณและการผูกพันงบประมาณข้ามปี (Multi-year Promised Grant) เปลี่ยนแปลงไปอย่างไร?",
